export interface WorldCity {
  name: string;
  offset: number;
}

export interface ClockTheme {
  id: string;
  name: string;
  bg: string;
  face: string;
  hand: string;
}

export type AppMode = 'clock' | 'worldclock' | 'stopwatch';

import { useState, useEffect } from 'react';
import { ClockTheme } from './types';

interface ClockFaceProps {
  date: Date;
  theme?: ClockTheme;
}

export default function ClockFace({ date }: ClockFaceProps) {
  const [seconds, setSeconds] = useState<number>(date.getSeconds());
  const [minutes, setMinutes] = useState<number>(date.getMinutes());
  const [hours, setHours] = useState<number>(date.getHours());

  useEffect(() => {
    setSeconds(date.getSeconds() + date.getMilliseconds() / 1000);
    setMinutes(date.getMinutes() + date.getSeconds() / 60);
    setHours((date.getHours() % 12) + date.getMinutes() / 60);
  }, [date]);

  const secondDeg = seconds * 6;
  const minuteDeg = minutes * 6;
  const hourDeg = hours * 30;

  return (
    <div className="clock-container">
      <div className="clock-face">
        {[...Array(12)].map((_, i) => (
          <div key={i} className="number" style={{ transform: `rotate(${i * 30}deg)` }}>
            <span style={{ transform: `rotate(-${i * 30}deg)` }}>{i === 0 ? 12 : i}</span>
          </div>
        ))}
        <div 
          className="hand hour-hand" 
          style={{ transform: `translateX(-50%) rotate(${hourDeg}deg)` }} 
        />
        <div 
          className="hand minute-hand" 
          style={{ transform: `translateX(-50%) rotate(${minuteDeg}deg)` }} 
        />
        <div 
          className="hand second-hand" 
          style={{ transform: `translateX(-50%) rotate(${secondDeg}deg)` }} 
        />
        <div className="center-dot" />
      </div>
    </div>
  );
}

import { AppMode, WorldCity, ClockTheme } from './types';

interface ClockControlsProps {
  mode: AppMode;
  setMode: (mode: AppMode) => void;
  cities?: WorldCity[];
  selectedCity?: WorldCity;
  setSelectedCity?: (city: WorldCity) => void;
  themes?: ClockTheme[];
  currentTheme?: ClockTheme;
  setTheme?: (theme: ClockTheme) => void;
  stopwatchTime?: number;
  isStopwatchRunning?: boolean;
  startStopwatch?: () => void;
  stopStopwatch?: () => void;
  resetStopwatch?: () => void;
  digitalTimeString?: string;
}

export default function ClockControls({
  mode,
  setMode,
  cities = [],
  selectedCity,
  setSelectedCity,
  themes = [],
  currentTheme,
  setTheme,
  stopwatchTime = 0,
  isStopwatchRunning = false,
  startStopwatch,
  stopStopwatch,
  resetStopwatch,
  digitalTimeString = '',
}: ClockControlsProps) {
  const formatStopwatch = (ms: number) => {
    const minutes = Math.floor(ms / 60000);
    const seconds = Math.floor((ms % 60000) / 1000);
    const milliseconds = Math.floor((ms % 1000) / 10);
    return `${String(minutes).padStart(2, '0')}:${String(seconds).padStart(2, '0')}.${String(milliseconds).padStart(2, '0')}`;
  };

  return (
    <div className="controls">
      <div className="mode-selector">
        <button 
          className={`btn ${mode === 'clock' ? 'btn-primary' : ''}`} 
          onClick={() => setMode('clock')}
        >
          時計
        </button>
        <button 
          className={`btn ${mode === 'worldclock' ? 'btn-primary' : ''}`} 
          onClick={() => setMode('worldclock')}
        >
          世界時計
        </button>
        <button 
          className={`btn ${mode === 'stopwatch' ? 'btn-primary' : ''}`} 
          onClick={() => setMode('stopwatch')}
        >
          ストップウォッチ
        </button>
      </div>

      <div className="digital-time">
        {mode === 'stopwatch' ? formatStopwatch(stopwatchTime) : digitalTimeString}
      </div>

      {mode === 'worldclock' && (
        <div style={{ marginTop: '10px', display: 'flex', gap: '5px', flexWrap: 'wrap', justifyContent: 'center' }}>
          {cities.map((city) => (
            <button
              key={city.name}
              className={`btn ${selectedCity?.name === city.name ? 'btn-primary' : ''}`}
              onClick={() => setSelectedCity?.(city)}
            >
              {city.name} (UTC{city.offset >= 0 ? `+${city.offset}` : city.offset})
            </button>
          ))}
        </div>
      )}

      {mode === 'stopwatch' && (
        <div style={{ marginTop: '10px', display: 'flex', gap: '10px', justifyContent: 'center' }}>
          {!isStopwatchRunning ? (
            <button className="btn btn-primary" onClick={() => startStopwatch?.()}>スタート</button>
          ) : (
            <button className="btn" onClick={() => stopStopwatch?.()}>ストップ</button>
          )}
          <button className="btn" onClick={() => resetStopwatch?.()}>リセット</button>
        </div>
      )}

      {themes.length > 0 && currentTheme && setTheme && (
        <div style={{ marginTop: '20px', display: 'flex', gap: '5px', justifyContent: 'center', alignItems: 'center' }}>
          <span style={{ fontSize: '14px' }}>テーマ: </span>
          {themes.map((th) => (
            <button
              key={th.id}
              className={`btn ${currentTheme.id === th.id ? 'btn-primary' : ''}`}
              onClick={() => setTheme(th)}
              style={{ fontSize: '12px', padding: '4px 8px' }}
            >
              {th.name}
            </button>
          ))}
        </div>
      )}
    </div>
  );
}

import { useState, useEffect } from 'react';
import { AppMode, WorldCity, ClockTheme } from './types';
import ClockFace from './ClockFace';
import ClockControls from './ClockControls';

const CITIES: WorldCity[] = [
  { name: '東京', offset: 9 },
  { name: 'ロンドン', offset: 0 },
  { name: 'ニューヨーク', offset: -5 },
  { name: 'シドニー', offset: 10 },
  { name: 'パリ', offset: 1 },
];

const THEMES: ClockTheme[] = [
  { id: 'default', name: '標準', bg: '#f0f0f0', face: '#ffffff', hand: '#333333' },
  { id: 'dark', name: 'ダーク', bg: '#1a1a1a', face: '#2c2c2c', hand: '#ffffff' },
  { id: 'blue', name: 'ブルー', bg: '#e0f7fa', face: '#ffffff', hand: '#006064' },
];

export default function App() {
  const [mode, setMode] = useState<AppMode>('clock');
  const [currentDate, setCurrentDate] = useState<Date>(new Date());
  const [selectedCity, setSelectedCity] = useState<WorldCity>(CITIES[0]);
  const [currentTheme, setCurrentTheme] = useState<ClockTheme>(THEMES[0]);

  const [stopwatchTime, setStopwatchTime] = useState<number>(0);
  const [isStopwatchRunning, setIsStopwatchRunning] = useState<boolean>(false);

  useEffect(() => {
    const timer = setInterval(() => {
      const now = new Date();
      if (mode === 'worldclock') {
        const utc = now.getTime() + now.getTimezoneOffset() * 60000;
        const cityTime = new Date(utc + 3600000 * selectedCity.offset);
        setCurrentDate(cityTime);
      } else {
        setCurrentDate(now);
      }
    }, 50);

    return () => clearInterval(timer);
  }, [mode, selectedCity]);

  useEffect(() => {
    let interval: ReturnType<typeof setInterval>;
    if (isStopwatchRunning) {
      const startTime = Date.now() - stopwatchTime;
      interval = setInterval(() => {
        setStopwatchTime(Date.now() - startTime);
      }, 10);
    }
    return () => clearInterval(interval);
  }, [isStopwatchRunning, stopwatchTime]);

  const startStopwatch = () => setIsStopwatchRunning(true);
  const stopStopwatch = () => setIsStopwatchRunning(false);
  const resetStopwatch = () => {
    setIsStopwatchRunning(false);
    setStopwatchTime(0);
  };

  const digitalTimeString = currentDate.toLocaleTimeString();

  return (
    <div className="app-container" style={{ background: currentTheme.bg, minHeight: '100vh', display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', padding: '20px' }}>
      <header className="header" style={{ textAlign: 'center', marginBottom: '20px' }}>
        <h1 style={{ margin: '0 0 10px 0', fontSize: '24px' }}>アナログ時計アプリ</h1>
        {mode === 'worldclock' && <p style={{ margin: 0 }}>世界時計: {selectedCity.name}</p>}
      </header>

      <div style={{ 
        backgroundColor: currentTheme.face, 
        padding: '20px', 
        borderRadius: '50%', 
        boxShadow: '0 4px 15px rgba(0,0,0,0.1)' 
      }}>
        <ClockFace date={currentDate} theme={currentTheme} />
      </div>

      <ClockControls
        mode={mode}
        setMode={setMode}
        cities={CITIES}
        selectedCity={selectedCity}
        setSelectedCity={setSelectedCity}
        themes={THEMES}
        currentTheme={currentTheme}
        setTheme={setCurrentTheme}
        stopwatchTime={stopwatchTime}
        isStopwatchRunning={isStopwatchRunning}
        startStopwatch={startStopwatch}
        stopStopwatch={stopStopwatch}
        resetStopwatch={resetStopwatch}
        digitalTimeString={digitalTimeString}
      />
    </div>
  );
}
